mapper.select:
SELECT * FROM (
SELECT shopwizard.tCatProd.*, shopwizard.tCatCate.CateName, shopwizard.tCmpShop.ShopName,
       shopion.tPrdProdDeliFee.DeliFeeName
FROM shopwizard.tCatProd
INNER JOIN shopwizard.tCmpShop ON shopwizard.tCmpShop.ShopCode = shopwizard.tCatProd.ShopCode
LEFT OUTER JOIN shopwizard.tCatCate ON shopwizard.tCatCate.CateCode = shopwizard.tCatProd.CateCode AND shopwizard.tCmpShop.SvcCode = shopwizard.tCatCate.SvcCode
LEFT OUTER JOIN shopion.tPrdProdDeliFee ON shopion.tPrdProdDeliFee.DeliFeeId = shopwizard.tCatProd.DeliFeeId


        AND (shopwizard.tCatProd.ProdCode = #{pProdCode} OR shopwizard.tCatProd.ShopProdCode = #{pProdCode} OR shopwizard.tCatProd.ImpaProdCode = #{pProdCode})

    AND shopwizard.tCatProd.CateCode = #{pCateCode}
    AND shopwizard.tCatProd.ShopCode = #{pShopCode}
    AND shopwizard.tCmpShop.SvcCode = #{pSvcCode}
    AND ShopProdCode = #{pShopProdCode}
    AND ImpaProdCode = #{pImpaProdCode}

        AND (shopwizard.tCatProd.ProdName LIKE CONCAT('%',REPLACE(#{pProdName},' ','%'),'%')
          OR shopwizard.tCatProd.ProdDsplName LIKE CONCAT('%',REPLACE(#{pProdName},' ','%'),'%')
          OR ShopProdCode = #{pProdName})

    AND shopwizard.tCatProd.SaleYn = #{pSaleYn}
    AND shopwizard.tCatProd.ApprovDate IS NULL
    AND shopwizard.tCatProd.ApprovDate IS NOT NULL

        AND NOT EXISTS (SELECT ProdCode FROM shopwizard.tCatProdChnl WHERE ProdCode = shopwizard.tCatProd.ProdCode AND ChnlCode = #{pUnRegistChnlCode})


        AND (shopwizard.tCatProd.ChangeDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND shopwizard.tCatProd.ChangeDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))


) T1

    ORDER BY ShopProdCode ${sord}
    ORDER BY ${sidx} ${sord}
    ORDER BY ProdCode DESC

LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCatProd
INNER JOIN shopwizard.tCmpShop ON shopwizard.tCmpShop.ShopCode = shopwizard.tCatProd.ShopCode
LEFT OUTER JOIN shopwizard.tCatCate ON shopwizard.tCatCate.CateCode = shopwizard.tCatProd.CateCode AND shopwizard.tCmpShop.SvcCode = shopwizard.tCatCate.SvcCode


        AND (shopwizard.tCatProd.ProdCode = #{pProdCode} OR shopwizard.tCatProd.ShopProdCode = #{pProdCode} OR shopwizard.tCatProd.ImpaProdCode = #{pProdCode})

    AND shopwizard.tCatProd.CateCode = #{pCateCode}
    AND shopwizard.tCatProd.ShopCode = #{pShopCode}
    AND shopwizard.tCmpShop.SvcCode = #{pSvcCode}
    AND ShopProdCode = #{pShopProdCode}
    AND ImpaProdCode = #{pImpaProdCode}

        AND (shopwizard.tCatProd.ProdName LIKE CONCAT('%',REPLACE(#{pProdName},' ','%'),'%')
          OR shopwizard.tCatProd.ProdDsplName LIKE CONCAT('%',REPLACE(#{pProdName},' ','%'),'%')
          OR ShopProdCode = #{pProdName})

    AND shopwizard.tCatProd.SaleYn = #{pSaleYn}
    AND shopwizard.tCatProd.ApprovDate IS NULL
    AND shopwizard.tCatProd.ApprovDate IS NOT NULL

        AND NOT EXISTS (SELECT ProdCode FROM shopwizard.tCatProdChnl WHERE ProdCode = shopwizard.tCatProd.ProdCode AND ChnlCode = #{pUnRegistChnlCode})


        AND (shopwizard.tCatProd.ChangeDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND shopwizard.tCatProd.ChangeDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))

SELECT P.ShopCode, S.ShopName, SUM(CASE WHEN P.SaleYn = 1 THEN 1 ELSE 0 END) AS SaleYesCount, SUM(CASE WHEN P.SaleYn = 0 THEN 1 ELSE 0 END) AS SaleNoCount, SUM(CASE WHEN P.SaleYn = -1 THEN 1 ELSE 0 END) AS SaleReadyCount, SUM(CASE WHEN P.SaleYn = -9 THEN 1 ELSE 0 END) AS SaleDeleteCount FROM shopwizard.tCatProd P INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = P.ShopCode
AND S.SvcCode = #{pSvcCode} AND P.ShopCode = #{pShopCode}
GROUP BY P.ShopCode, S.ShopName ORDER BY 3 DESC, 4, 2

